evidence.en:
postgres.log:
  ERROR:  deadlock detected
  DETAIL: Process 4321 waits for ShareLock on transaction 998; blocked by process 1234.
          Process 1234 waits for ShareLock on transaction 997; blocked by process 4321.
  HINT:   See server log for query details.

app.log:
  worker-A: ERROR: deadlock detected (SQLSTATE 40P01)  <- crashes the job
  worker-B: reconciliation batch finished OK

// worker-A: UPDATE accounts SET ... WHERE id = 1; then WHERE id = 2;
// worker-B: UPDATE accounts SET ... WHERE id = 2; then WHERE id = 1;

